def transform(grid):
    """Extend each foreground marker upward and leftward in color 2.

    Rays stop at another foreground marker; original markers/background stay
    unchanged otherwise.
    """
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    fg = max((v for v in counts if v != bg), key=lambda v: counts[v])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != fg:
                continue
            for rr in range(r - 1, -1, -1):
                if grid[rr][c] == fg:
                    break
                if grid[rr][c] == bg:
                    out[rr][c] = 2
            for cc in range(c - 1, -1, -1):
                if grid[r][cc] == fg:
                    break
                if grid[r][cc] == bg:
                    out[r][cc] = 2
    return out
