            out[r0][c] = 2
        if grid[r1][c] == background:
            out[r1][c] = 2
    for r in range(r0, r1 + 1):
        if grid[r][c0] == background:
            out[r][c0] = 2
        if grid[r][c1] == background:
            out[r][c1] = 2

    # Dense interior alignments are lines; bridge their successive markers.
    for r in range(r0 + 1, r1):
        cols = [c for c in range(c0, c1 + 1) if grid[r][c] == foreground]
        if len(cols) >= 4:
