def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    foreground = max((color for color in counts if color != background), key=counts.get)
    out = [row[:] for row in grid]

    # Bridge gaps only along established marker lines (at least three markers).
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == foreground]
        if len(cols) >= 3:
